const val MOD: UInt = 1000000007u

data class ModInt(val v: UInt) {
    operator fun plus(other: ModInt): ModInt {
        var d = v + other.v
        if (d >= MOD) {
            d -= MOD
        }
        return ModInt(d)
    }

    operator fun minus(other: ModInt): ModInt {
        var d = v + MOD - other.v
        if (d >= MOD) {
            d -= MOD
        }
        return ModInt(d)
    }

    operator fun times(other: ModInt): ModInt {
        val res = (v.toULong() * other.v.toULong()) % MOD.toULong()
        return ModInt(res.toUInt())
    }

    operator fun div(other: UInt): ModInt {
        return this * ModInt(other).pow(MOD - 2u)
    }

    operator fun div(other: ModInt): ModInt {
        return this * other.pow(MOD - 2u)
    }

    operator fun unaryMinus(): ModInt {
        return if (v == 0u) ModInt(0u) else ModInt(MOD - v)
    }

    fun pow(mutN: UInt): ModInt {
        var n = mutN
        var t = ModInt.new(1u)
        var s = this
        while (n > 0u) {
            if ((n and 1u) == 1u) {
                t *= s
            }
            s *= s
            n = n shr 1
        }
        return t
    }

    operator fun plusAssign(other: ModInt) {
        val r = this + other
        thisRef.v = r.v
    }

    operator fun minusAssign(other: ModInt) {
        val r = this - other
        thisRef.v = r.v
    }

    operator fun timesAssign(other: ModInt) {
        val r = this * other
        thisRef.v = r.v
    }

    operator fun divAssign(other: ModInt) {
        val r = this / other
        thisRef.v = r.v
    }

    companion object {
        fun new(v: UInt): ModInt {
            return ModInt(v % MOD)
        }

        // workaround for mutable operations
        private val ModInt.thisRef: ModInt
            get() = this
    }
}

class Precalc(private val n: Int) {
    private val inv: MutableList<ModInt> = MutableList(n + 1) { ModInt(1u) }
    private val fact: MutableList<ModInt> = MutableList(n + 1) { ModInt(1u) }
    private val ifact: MutableList<ModInt> = MutableList(n + 1) { ModInt(1u) }

    init {
        for (i in 1..n) {
            if (i > 2) {
                inv[i] = -inv[(MOD.toInt() % i)] * ModInt((MOD / i.toUInt()))
            }
            fact[i] = ModInt(i.toUInt()) * fact[i - 1]
            ifact[i] = inv[i] * ifact[i - 1]
        }
    }

    fun fact(n: Int): ModInt {
        return fact[n]
    }

    fun inv(x: Int): ModInt {
        return inv[x]
    }

    fun ifact(x: Int): ModInt {
        return ifact[x]
    }

    fun comb(n: Int, k: Int): ModInt {
        if (k > n) return ModInt(0u)
        return fact[n] * ifact[k] * ifact[n - k]
    }
}

