class ModIntSemiRing(private val value: ModInt) : SemiRing<ModIntSemiRing> {
    override fun zero(): ModIntSemiRing = ModIntSemiRing(ModInt(0u))
    override fun one(): ModIntSemiRing = ModIntSemiRing(ModInt(1u))
    override fun plus(other: ModIntSemiRing): ModIntSemiRing = ModIntSemiRing(this.value + other.value)
    override fun times(other: ModIntSemiRing): ModIntSemiRing = ModIntSemiRing(this.value * other.value)
    override fun toString(): String = value.v.toString()
    fun unwrap(): ModInt = value
}

fun main() {
    val reader = System.`in`.bufferedReader()
    val tokens = reader.readLine().trim().split(" ")
    var n = tokens[0].toULong()
    val m = tokens[1].toInt()

    val one = ModIntSemiRing(ModInt(1u))
    val zero = ModIntSemiRing(ModInt(0u))

    typealias M = SquareMatrix<ModIntSemiRing>

    var t = SquareMatrix.identity(m, one, zero)
    var s = SquareMatrix.zero(m, zero)

    for (i in 1 until m) {
        s.setAt(i - 1, i, ModIntSemiRing(ModInt(1u)))
    }
    s.setAt(m - 1, 0, ModIntSemiRing(ModInt(1u)))
    s.setAt(m - 1, m - 1, ModIntSemiRing(ModInt(1u)))

    while (n > 0uL) {
        if ((n and 1uL) == 1uL) {
            t = t * s
        }
        s = s * s
        n = n shr 1
    }

    val ans = t.getAt(m - 1, m - 1)
    println(ans.unwrap().v)
}

