        require(n == rhs.n)
        val c = zero(n, a[0])
        for (i in 0 until n * n) {
            c.a[i] = a[i] + rhs.a[i]
        }
        return c
    }

    operator fun times(rhs: SquareMatrix<T>): SquareMatrix<T> {
        require(n == rhs.n)
        val c = zero(n, a[0])
