                    c.a[rowStart + j] = c.a[rowStart + j] + (ak * rhs.a[rhsStart + j])
                }
            }
        }
        return c
    }

    fun cloneMatrix(): SquareMatrix<T> {
        return SquareMatrix(n, a.toMutableList())
    }
