private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var len = 0
    private var ptr = 0

    private fun readByte(): Int {
        if (ptr >= len) {
            len = input.read(buffer)
            ptr = 0
            if (len <= 0) return -1
        }
        return buffer[ptr++].toInt()
    }

    fun nextLong(): Long {
        var c = readByte()
        while (c <= 32 && c >= 0) c = readByte()
        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }
        var res = 0L
        while (c > 32) {
            res = res * 10 + (c - 48)
            c = readByte()
        }
        return res * sign
    }

    fun nextInt(): Int = nextLong().toInt()
}

fun run() {
    val fs = FastScanner()
    val nInput = fs.nextLong()
    val m = fs.nextInt()
    typealias M = SquareMatrix<ModInt>
    var t = SquareMatrix.identity(m, ModIntSemiRing)
    var s = SquareMatrix.zero(m, ModIntSemiRing)
    for (i in 1 until m) {
