    }
    s.setAt(m - 1, 0, ModInt(1))
    s.setAt(m - 1, m - 1, ModInt(1))
    var n = nInput
    while (n > 0) {
        if ((n and 1L) == 1L) {
            t = t * s.cloneMatrix()
        }
        s = s.cloneMatrix() * s
        n = n shr 1
    }
    val ans = t.getAt(m - 1, m - 1)
    val out = PrintWriter(System.out)
    out.println(ans)
    out.flush()
}

fun main() {
    run()
}

